import{_ as p,a0 as i,w as d,s as a,ao as l,I as s,x as n,a1 as o,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"CentOS 7.x中正確設置時間與時鐘服務器同步 | LCTT x X-CMD","titleTemplate":false,"description":"CentOS 7.x中正確設置時間與時鐘服務器同步 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"CentOS 7.x中正確設置時間與時鐘服務器同步 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"CentOS 7.x中正確設置時間與時鐘服務器同步 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141222 How to Sync Time Properly with NTP Server in CentOS 7.x","title":"CentOS 7.x中正確設置時間與時鐘服務器同步","tag":"201501","desc":""},"relativePath":"201501/20141222 How to Sync Time Properly with NTP Server in CentOS 7.x.md","filePath":"[post].md"}'),c={name:"201501/20141222 How to Sync Time Properly with NTP Server in CentOS 7.x.md"};function m(g,t,h,y,x,T){const r=i("Link");return d(),a("div",null,[t[13]||(t[13]=l(`<h1 id="centos-7-x中正確設置時間與時鐘服務器同步" tabindex="-1">CentOS 7.x中正確設置時間與時鐘服務器同步 <a class="header-anchor" href="#centos-7-x中正確設置時間與時鐘服務器同步" aria-label="Permalink to “CentOS 7.x中正確設置時間與時鐘服務器同步”">​</a></h1><p><strong>Chrony</strong>是一個開源的自由軟件，它能幫助你保持系統時鐘與時鐘服務器（NTP）同步，因此讓你的時間保持精確。它由兩個程序組成，分別是chronyd和chronyc。chronyd是一個後台運行的守護進程，用於調整內核中運行的系統時鐘和時鐘服務器同步。它確定計算機增減時間的比率，並對此進行補償。chronyc提供了一個用户界面，用於監控性能並進行多樣化的配置。它可以在chronyd實例控制的計算機上工作，也可以在一台不同的遠程計算機上工作。</p><p>在像CentOS 7之類基於RHEL的操作系統上，已經默認安裝有Chrony。</p><h3 id="chrony配置" tabindex="-1">Chrony配置 <a class="header-anchor" href="#chrony配置" aria-label="Permalink to “Chrony配置”">​</a></h3><p>當Chrony啓動時，它會讀取/etc/chrony.conf配置文件中的設置。CentOS 7操作系統上最重要的設置有：</p><p><strong>server</strong> - 該參數可以多次用於添加時鐘服務器，必須以&quot;server &quot;格式使用。一般而言，你想添加多少服務器，就可以添加多少服務器。</p><pre><code>server 0.centos.pool.ntp.org
server 3.europe.pool.ntp.org
</code></pre><p><strong>stratumweight</strong> - stratumweight指令設置當chronyd從可用源中選擇同步源時，每個層應該添加多少距離到同步距離。默認情況下，CentOS中設置為0，讓chronyd在選擇源時忽略源的層級。</p><p><strong>driftfile</strong> - chronyd程序的主要行為之一，就是根據實際時間計算出計算機增減時間的比率，將它記錄到一個文件中是最合理的，它會在重啓後為系統時鐘作出補償，甚至可能的話，會從時鐘服務器獲得較好的估值。</p><p><strong>rtcsync</strong> - rtcsync指令將啓用一個內核模式，在該模式中，系統時間每11分鐘會拷貝到實時時鐘（RTC）。</p><p><strong>allow / deny</strong> - 這裏你可以指定一台主機、子網，或者網絡以允許或拒絕NTP連接到扮演時鐘服務器的機器。</p><pre><code>allow 192.168.4.5
deny 192.168/16
</code></pre><p><strong>cmdallow / cmddeny</strong> - 跟上面相類似，只是你可以指定哪個IP地址或哪台主機可以通過chronyd使用控制命令</p><p><strong>bindcmdaddress</strong> - 該指令允許你限制chronyd監聽哪個網絡接口的命令包（由chronyc執行）。該指令通過cmddeny機制提供了一個除上述限制以外可用的額外的訪問控制等級。</p><pre><code>bindcmdaddress 127.0.0.1
bindcmdaddress ::1
</code></pre><p><strong>makestep</strong> - 通常，chronyd將根據需求通過減慢或加速時鐘，使得系統逐步糾正所有時間偏差。在某些特定情況下，系統時鐘可能會漂移過快，導致該調整過程消耗很長的時間來糾正系統時鐘。該指令強制chronyd在調整期大於某個閥值時步進調整系統時鐘，但只有在因為chronyd啓動時間超過指定限制（可使用負值來禁用限制），沒有更多時鐘更新時才生效。</p><h3 id="使用chronyc" tabindex="-1">使用chronyc <a class="header-anchor" href="#使用chronyc" aria-label="Permalink to “使用chronyc”">​</a></h3><p>你也可以通過運行chronyc命令來修改設置，命令如下：</p><p><strong>accheck</strong> - 檢查NTP訪問是否對特定主機可用</p><p><strong>activity</strong> - 該命令會顯示有多少NTP源在線/離線</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/chrony-activity.jpg" alt=""></p><p><strong>add server</strong> - 手動添加一台新的NTP服務器。</p><p><strong>clients</strong> - 在客户端報告已訪問到服務器</p><p><strong>delete</strong> - 手動移除NTP服務器或對等服務器</p><p><strong>settime</strong> - 手動設置守護進程時間</p><p><strong>tracking</strong> - 顯示系統時間信息</p><p>你可以通過使用幫助命令查看完整的命令列表：</p><p><img src="http://blog.linoxide.com/wp-content/uploads/2014/10/commands.jpg" alt=""></p><hr>`,29)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),o(r,{href:"http://linoxide.com/linux-command/chrony-time-sync/"},{default:e(()=>[...t[0]||(t[0]=[n("http://linoxide.com/linux-command/chrony-time-sync/",-1)])]),_:1})]),s("p",null,[t[5]||(t[5]=n("作者：",-1)),o(r,{href:"http://linoxide.com/author/adriand/"},{default:e(()=>[...t[2]||(t[2]=[n("Adrian Dinu",-1)])]),_:1}),t[6]||(t[6]=n(" 譯者：",-1)),o(r,{href:"https://github.com/GOLinux"},{default:e(()=>[...t[3]||(t[3]=[n("GOLinux",-1)])]),_:1}),t[7]||(t[7]=n(" 校對：",-1)),o(r,{href:"https://github.com/wxy"},{default:e(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),s("p",null,[t[10]||(t[10]=n("本文由 ",-1)),o(r,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原創翻譯，",-1)),o(r,{href:"http://linux.cn/"},{default:e(()=>[...t[9]||(t[9]=[n("Linux中國",-1)])]),_:1}),t[12]||(t[12]=n(" 榮譽推出",-1))])])}const S=p(c,[["render",m]]);export{f as __pageData,S as default};
